import{_ as a,o as t,c as i,ao as r}from"./chunks/framework.hkilgvYh.js";const h=JSON.parse('{"title":"Roadmap","description":"","frontmatter":{},"headers":[],"relativePath":"roadmap.md","filePath":"roadmap.md","lastUpdated":null}'),o={name:"roadmap.md"};function n(l,e,s,p,d,c){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="Roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#Roadmap" aria-label="Permalink to &quot;Roadmap {#Roadmap}&quot;">​</a></h1><p>The Australian Electricity Market Operator makes available a wealth of market data and forecasts. This unique transparency and further the availability of public GIS data sources should allow to derive a relatively accurate model of the Eastern Australian power grid, making it a perfect test bed with real data.</p><p>The following points are the planned next steps in the development of this package:</p><h2 id="Short-term" tabindex="-1">Short-term <a class="header-anchor" href="#Short-term" aria-label="Permalink to &quot;Short-term {#Short-term}&quot;">​</a></h2><ul><li><p>[ ] Inclusion of all unit types in the system.</p></li><li><p>[ ] Review assumptions made for the operational costs.</p></li><li><p>[ ] Create a full network configuration with all lines (using GIS data) for AC/DC operation problems (work started in <a href="https://github.com/ymiftah/nemdb" target="_blank" rel="noreferrer">nemdb</a>).</p></li><li><p>[ ] Account for Commissioning / Decommissioning dates to model the system at different years.</p></li><li><p>[ ] Parse latest ISP assumptions for operation costs.</p></li><li><p>[x] Enforce the FCAS trapezium and joint capacity/ramping constraints (see <a href="/AustralianElectricityMarkets.jl/previews/PR110/examples/nemde_fcas#nemde-fcas">FCAS capability and co-optimisation</a>) inside a <code>PowerSimulations.jl</code> dispatch problem, and interconnector constraints.</p></li><li><p>[x] Separate the data download and cache population into its own package, <code>AustralianElectricityMarketsData</code>.</p></li><li><p>[x] Run NEMDE dispatch on real intervals and compare with the published outcome (see <a href="/AustralianElectricityMarkets.jl/previews/PR110/examples/run_nemde#run-nemde">Running NEMDE dispatch</a>).</p></li><li><p>[x] Closed-loop run, in which each interval starts from the previous solve (<code>NEMClosedLoopDispatchProblem</code>).</p></li><li><p>[x] Fast-start inflexibility profiles, dispatched in two runs per interval (see <a href="/AustralianElectricityMarkets.jl/previews/PR110/examples/nemde_fast_start#nemde-fast-start">Fast-start dispatch</a>).</p></li><li><p>[ ] Carry the fast-start end state from one interval to the next in a closed-loop run.</p></li></ul><h2 id="Mid/Long-term" tabindex="-1">Mid/Long-term <a class="header-anchor" href="#Mid/Long-term" aria-label="Permalink to &quot;Mid/Long-term {#Mid/Long-term}&quot;">​</a></h2><ul><li><p>[ ] Extend the parsing of ISP inputs.</p></li><li><p>[ ] Interface with <a href="https://github.com/GenXProject/GenX.jl" target="_blank" rel="noreferrer">GenX</a> for resource capacity expansion modelling.</p></li><li><p>[ ] Develop a general interface in a package <code>ElectricityMarkets.jl</code>.</p></li><li><p>[ ] Full documentation of the interface.</p></li><li><p>[ ] PoC of the interface with another region&#39;s electricity market.</p></li></ul>',7)])])}const u=a(o,[["render",n]]);export{h as __pageData,u as default};
